import {LESSON,RESIDENTS,STOP,BUS_STARTS} from './data.js';
import {evaluate,summary,time} from './engine.js';
import {connectBackend,createClass,readClass,watchClass,updateControl,joinClass,updateTeam,backendMode} from './classroom.js';

const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phaseNames=LESSON.map(x=>x[0]);
const route=()=>location.hash.replace(/^#\/?/,'').split('?')[0].split('/').filter(Boolean);
let dispose=()=>{},dashboardTimer,latestClass,currentCode,qrOpen=false,detailTeam=null,busy=false;

function shell(content,kind=''){document.body.className=kind;app.innerHTML=content;bindCommon();}
function logo(){return `<div class="portal-brand"><span class="portal-bus">▣</span><div><b>이 버스는 누구를 지나치는가</b><small>고등학교 통합사회 · 노선 설계 활동</small></div></div>`;}
function notice(text,type=''){return `<p class="portal-notice ${type}">${esc(text)}</p>`;}
function setNotice(text,type=''){const el=document.querySelector('#portal-notice');if(el){el.className=`portal-notice ${type}`;el.textContent=text;}}
function bindCommon(){document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',()=>{location.hash=el.dataset.nav;}));}

function renderLanding(){dispose();clearInterval(dashboardTimer);shell(`<main class="portal-page minimal-entry"><section class="entry-stage"><div class="entry-map" aria-hidden="true"><img src="./assets/town-map.png" alt=""><span class="portal-pin p1">언덕마을</span><span class="portal-pin p2">환승센터</span><span class="portal-pin p3">병원</span></div><section class="entry-launch" aria-label="교사용 세션 만들기"><button class="portal-primary" id="create-class">새 수업 만들기</button><p id="portal-notice" class="portal-notice" role="status"></p></section></section></main>`,'portal-mode');
 $('#create-class').addEventListener('click',async()=>{if(busy)return;busy=true;const b=$('#create-class');b.disabled=true;b.textContent='수업 여는 중…';try{const klass=await createClass();sessionStorage.setItem('bus-auto-qr',klass.code);location.hash=`teacher/${klass.code}`;}catch(e){setNotice(firebaseMessage(e),'error');b.disabled=false;b.textContent='새 수업 만들기';busy=false;}});
}
const $=s=>document.querySelector(s);
function firebaseMessage(e){const raw=String(e?.message||e);if(raw.includes('auth/operation-not-allowed'))return 'Firebase에서 익명 로그인을 켜야 수업을 만들 수 있습니다.';if(raw.includes('PERMISSION_DENIED'))return 'Firebase 데이터베이스 규칙을 확인해 주세요.';if(raw.includes('configuration-not-found'))return 'Firebase Authentication을 먼저 시작해 주세요.';return raw.replace(/^Firebase:\s*/,'');}

async function renderJoin(code){dispose();clearInterval(dashboardTimer);shell(`<main class="join-page"><header class="join-head">${logo()}<button class="portal-ghost" data-nav="">처음으로</button></header><section class="join-card"><div class="join-art"><img src="./assets/town-map.png" alt="강과 다리로 이어진 활동 속 가상 도시"><span>수업 코드 <b>${esc(code)}</b></span></div><div class="join-form"><p class="portal-kicker">학생용 입장</p><h1>우리 모둠으로 참여하기</h1><p>모둠 이름은 선생님 화면에서 진행 상황을 구분하는 데 사용됩니다.</p><label for="team-name">모둠 이름</label><input id="team-name" maxlength="24" autocomplete="off" placeholder="예: 다리놓는사람들"><button class="portal-primary" id="join-team">수업에 입장하기</button><p id="portal-notice" class="portal-notice">수업을 확인하고 있어요.</p></div></section></main>`,'portal-mode');
 try{const klass=await readClass(code);if(!klass){setNotice('수업 코드를 찾을 수 없습니다. 선생님 화면의 코드를 확인해 주세요.','error');$('#join-team').disabled=true;return;}if(klass.control?.status==='ended'){setNotice('이미 종료된 수업입니다.','error');$('#join-team').disabled=true;return;}const savedId=localStorage.getItem(`bus-team-${code}`);if(savedId&&klass.teams?.[savedId]){await startStudent(code,klass.teams[savedId],klass);return;}setNotice(klass.control?.status==='lobby'?'입장하면 선생님이 수업을 시작할 때까지 기다립니다.':`${phaseNames[klass.control?.phase||0]} 단계가 진행 중입니다.`);$('#team-name').focus();}catch(e){setNotice(firebaseMessage(e),'error');}
 $('#join-team')?.addEventListener('click',async()=>{const name=$('#team-name').value.trim();if(!name){setNotice('모둠 이름을 입력해 주세요.','error');return;}const b=$('#join-team');b.disabled=true;b.textContent='입장 중…';try{const team=await joinClass(code,name);const klass=await readClass(code);await startStudent(code,team,klass);}catch(e){setNotice(firebaseMessage(e),'error');b.disabled=false;b.textContent='수업에 입장하기';}});
}
async function startStudent(code,team,klass){dispose();clearInterval(dashboardTimer);const storageKey=`bus-neighbors-v2-${code}-${team.uid}`;if(team.studentState&&!localStorage.getItem(storageKey))localStorage.setItem(storageKey,JSON.stringify(team.studentState));let syncTimer;
 window.BUS_CLASSROOM={code,teamId:team.uid,teamName:team.name,control:klass.control,storageKey,backend:backendMode(),sync(payload){clearTimeout(syncTimer);syncTimer=setTimeout(()=>updateTeam(code,team.uid,{studentState:payload.state,progress:{mode:payload.mode,attempts:payload.state.attempts.length,reflectionDone:payload.state.reflections.filter(Boolean).length,summary:payload.summary,results:payload.results,design:payload.state.design,updatedAt:Date.now()}}).catch(()=>window.dispatchEvent(new CustomEvent('classroom-sync-error'))),450);}};
 document.body.className='student-class-mode';app.innerHTML='<div class="portal-loading">마을 지도를 불러오는 중…</div>';dispose=watchClass(code,(value,error)=>{if(error||!value){window.BUS_CLASSROOM.control={status:'ended',phase:6,message:'수업 연결이 끊겼습니다.'};}else{window.BUS_CLASSROOM.control=value.control;window.BUS_CLASSROOM.teamName=value.teams?.[team.uid]?.name||team.name;}window.dispatchEvent(new CustomEvent('classroom-state'));});await import('./app.js');
}
async function startPreview(code){const klass=await readClass(code);if(!klass){renderNotFound();return;}window.BUS_CLASSROOM={code,teamId:'preview',teamName:'교사 리허설',control:{...klass.control,status:'active'},storageKey:`bus-preview-${code}`,backend:'preview',preview:true,sync(){}};document.body.className='student-class-mode';app.innerHTML='';await import('./app.js');}

function teacherHeader(k){return `<header class="teacher-header"><button class="portal-ghost" data-nav="">← 처음으로</button>${logo()}<div class="teacher-head-actions"><button class="class-code-button" data-action="qr"><small>수업 코드</small><b>${k.code}</b></button><button class="portal-ghost" data-action="preview">학생 화면 미리보기</button><button class="portal-ghost" data-action="qr">학생 입장 QR</button><button class="portal-ghost danger" data-action="${k.control.status==='ended'?'reopen':'end'}">${k.control.status==='ended'?'수업 다시 열기':'수업 종료'}</button></div></header>`;}
function remaining(k){const c=k.control;if(c.status==='lobby')return c.phaseDuration*60;if(c.status==='ended')return 0;const anchor=c.status==='paused'?(c.pausedAt||Date.now()):Date.now();return Math.max(0,c.phaseDuration*60-Math.floor((anchor-(c.phaseStartedAt||anchor))/1000));}
function timeDisplay(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function teamProgress(team){return team.progress||{mode:'waiting',attempts:0,reflectionDone:0,summary:{ontime:0,late:0,impossible:0}};}
function dashboardBody(k){const teams=Object.values(k.teams||{}).sort((a,b)=>a.joinedAt-b.joinedAt),submitted=teams.filter(t=>teamProgress(t).attempts>0).length,revised=teams.filter(t=>teamProgress(t).attempts>1).length,reflected=teams.filter(t=>teamProgress(t).reflectionDone===3).length,sec=remaining(k),phase=k.control.phase||0;
 const missed=RESIDENTS.map((p,i)=>({name:p.name,count:teams.filter(t=>teamProgress(t).results?.[i]?.status==='impossible').length,late:teams.filter(t=>teamProgress(t).results?.[i]?.status==='late').length})).sort((a,b)=>b.count-a.count||b.late-a.late).slice(0,5);
 return `<main class="teacher-main"><section class="stage-strip" aria-label="45분 수업 단계">${LESSON.map(([name,min],i)=>`<button class="stage-pill ${i===phase?'active':''} ${i<phase?'done':''}" data-action="phase" data-phase="${i}"><i>${i+1}</i><span>${name}<small>${min}분</small></span></button>`).join('')}</section><section class="dashboard-grid"><div class="dashboard-left"><article class="control-card"><div class="control-title"><div><p class="portal-kicker">현재 진행</p><h1>${phase+1}. ${phaseNames[phase]}</h1><p>${esc(k.control.message||stagePrompt(phase))}</p></div><div class="timer ${sec<60&&k.control.status==='active'?'urgent':''}"><small>${k.control.status==='paused'?'일시정지':k.control.status==='lobby'?'입장 대기':k.control.status==='ended'?'수업 종료':'남은 시간'}</small><strong id="teacher-timer">${timeDisplay(sec)}</strong></div></div><div class="control-actions">${k.control.status==='lobby'?`<button class="portal-primary" data-action="start">수업 시작</button>`:k.control.status==='ended'?`<button class="portal-primary" data-action="reopen">현재 단계에서 다시 열기</button>`:`<button class="portal-primary" data-action="pause">${k.control.status==='paused'?'계속 진행':'일시정지'}</button><button class="portal-ghost" data-action="extend">+ 1분</button><button class="portal-ghost" data-action="restart-timer">타이머 다시 시작</button><button class="portal-ghost" data-action="next" ${phase===6?'disabled':''}>다음 단계 →</button>`}</div><div class="broadcast"><label for="broadcast">학생 화면 안내 문구</label><input id="broadcast" maxlength="90" value="${esc(k.control.message||'')}" placeholder="예: 지각한 주민 한 명의 경로를 다시 살펴보세요."><button class="portal-ghost" data-action="broadcast">보내기</button></div></article><article class="teams-card"><div class="card-head"><div><p class="portal-kicker">실시간 모둠 현황</p><h2>입장한 모둠 ${teams.length}개</h2></div><div class="mini-stats"><span>첫 결과 <b>${submitted}/${teams.length}</b></span><span>재설계 <b>${revised}/${teams.length}</b></span><span>성찰 완료 <b>${reflected}/${teams.length}</b></span></div></div>${teams.length?`<div class="team-table"><div class="team-row header"><span>모둠</span><span>현재 화면</span><span>시도</span><span>최근 결과<small>정시 · 지각 · 불가</small></span><span>성찰</span></div>${teams.map(t=>{const p=teamProgress(t),s=p.summary||{};return `<button class="team-row" data-action="team" data-team="${esc(t.uid)}"><span><b>${esc(t.name)}</b><small>${activeAgo(t.lastSeen)}</small></span><span>${modeLabel(p.mode)}</span><span>${p.attempts||0}회</span><span class="result-inline"><i class="ok" aria-label="정시 ${s.ontime||0}명">${s.ontime||0}</i><i class="late" aria-label="지각 ${s.late||0}명">${s.late||0}</i><i class="no" aria-label="이동 불가 ${s.impossible||0}명">${s.impossible||0}</i></span><span>${p.reflectionDone||0}/3</span></button>`;}).join('')}</div>`:'<div class="empty-teams"><span>⌁</span><h3>학생 모둠을 기다리고 있어요.</h3><p>학생 QR을 화면에 띄우거나 링크를 공유하세요.</p><button class="portal-primary" data-action="qr">학생 입장 QR 보기</button></div>'}</article></div><aside class="dashboard-side"><article class="side-card"><p class="portal-kicker">수업 진행 도구</p><button data-action="qr"><span>▦</span><div><b>학생 입장 QR</b><small>코드와 링크를 크게 표시</small></div></button><button data-action="print"><span>▤</span><div><b>자료 인쇄하기</b><small>주민 8명 요약 · A4 한쪽</small></div></button><button data-action="preview"><span>▣</span><div><b>학생 화면 미리보기</b><small>별도 기록 없이 리허설</small></div></button><button data-action="export"><span>⇩</span><div><b>수업 결과 내보내기</b><small>모둠별 JSON 기록</small></div></button></article><article class="side-card"><p class="portal-kicker">현재 주민별 결과</p><h3>많이 놓친 주민</h3>${teams.some(t=>teamProgress(t).results)?`<div class="missed-list">${missed.map(x=>`<div><b>${x.name}</b><span>이동 불가 ${x.count} · 지각 ${x.late}</span><i style="--w:${teams.length?(x.count+x.late)/teams.length*100:0}%"></i></div>`).join('')}</div>`:'<p class="side-empty">모둠이 첫 운행을 마치면 주민별 결과가 나타납니다.</p>'}</article><article class="side-card lesson-tip"><p class="portal-kicker">교사 질문</p><p>${teacherQuestion(phase)}</p></article></aside></section></main>`;}
function stagePrompt(i){return ['인쇄 자료에서 주민의 출발·도착·보행 조건을 확인하세요.','고정 기점에서 이어지는 두 노선과 저상버스 배치를 결정하세요.','첫 노선을 운행하고 주민별 결과를 저장하세요.','지각하거나 이동할 수 없는 주민의 이유를 찾으세요.','같은 도시 조건에서 노선을 다시 설계하세요.','첫 시도와 수정 시도의 변화를 비교하세요.','세 질문에 모둠의 생각을 기록하세요.'][i];}
function teacherQuestion(i){return ['출발 시각과 보행 조건이 서로 다른 주민은 누구인가요?','이 노선에서 가장 오래 기다릴 사람은 누구일까요?','예상과 실제 결과가 달랐던 주민은 누구인가요?','정류장은 있는데 이동하지 못한 주민이 있나요?','새 연결로 왕복 시간이 얼마나 늘었나요?','새로 이동 가능해진 사람과 더 오래 걸린 사람은 누구인가요?','정류장의 존재와 실질적인 이동 기회는 어떻게 다른가요?'][i];}
function activeAgo(t){if(!t)return '접속 기록 없음';const d=Math.max(0,Math.floor((Date.now()-t)/1000));return d<20?'지금 접속':d<60?`${d}초 전`:d<3600?`${Math.floor(d/60)}분 전`:'오래 전';}
function modeLabel(m){return ({waiting:'입장 대기',design:'노선 설계',run:'운행 중',results:'결과 비교',reflection:'생각 정리'}[m]||'활동 중');}
function qrModal(k){const link=`${location.origin}${location.pathname}#/join/${k.code}`,src=`https://api.qrserver.com/v1/create-qr-code/?size=420x420&margin=14&data=${encodeURIComponent(link)}`;return `<div class="portal-modal-shade"><section class="qr-modal" role="dialog" aria-modal="true" aria-labelledby="qr-title"><button class="modal-x" data-action="close-modal" aria-label="닫기">×</button><h2 id="qr-title">학생 입장 QR</h2><p>학생들은 아이패드 카메라로 스캔한 뒤 모둠 이름을 입력합니다.</p><img src="${src}" alt="수업 코드 ${k.code} 학생 입장 QR 코드"><div class="big-code"><small>수업 코드</small><b>${k.code}</b></div><div class="access-address"><small>QR 코드가 인식되지 않을 때 접속 주소</small><strong>${esc(link)}</strong></div><button class="copy-address" data-action="copy-link">접속 주소 복사</button></section></div>`;}
function teamModal(k,id){const t=k.teams?.[id];if(!t)return '';const p=teamProgress(t),res=p.results||[];return `<div class="portal-modal-shade"><section class="team-modal" role="dialog" aria-modal="true" aria-labelledby="team-title"><button class="modal-x" data-action="close-modal" aria-label="닫기">×</button><p class="portal-kicker">모둠 상세</p><h2 id="team-title">${esc(t.name)}</h2><div class="team-metrics"><span>시도 <b>${p.attempts||0}회</b></span><span>성찰 <b>${p.reflectionDone||0}/3</b></span><span>최근 활동 <b>${activeAgo(t.lastSeen)}</b></span></div>${res.length?`<div class="student-result-grid">${RESIDENTS.map((person,i)=>{const r=res[i]||{};return `<article><b>${person.name}</b><span>${person.destination} · ${r.arrival==null?'이동 불가':`${time(r.arrival)} 도착`}</span><i class="${r.status||'impossible'}">${r.status==='ontime'?'정시':r.status==='late'?'지각':'불가'}</i></article>`;}).join('')}</div>`:'<p class="side-empty">아직 저장된 운행 결과가 없습니다.</p>'}<button class="portal-primary modal-done" data-action="close-modal">확인</button></section></div>`;}
function renderPrint(){dispose();clearInterval(dashboardTimer);const cards=RESIDENTS.map((p,i)=>`<article class="print-resident"><header><b>${i+1}. ${esc(p.name)}</b><span>${esc(p.role)}${p.low?' · 저상버스 필요':''}</span></header><p class="print-story">${esc(p.story)}</p><dl><dt>이동</dt><dd>${esc(p.home)} → ${esc(p.destination)}</dd><dt>시간</dt><dd>${time(p.ready)}부터 출발 · ${time(p.deadline)}까지 도착</dd><dt>집 → 정류장</dt><dd>${Object.entries(p.access).map(([id,m])=>`${STOP[id].name} ${m}분`).join(' · ')}</dd><dt>하차 후</dt><dd>${Object.entries(p.egress).map(([id,m])=>`${STOP[id].name}에서 ${p.destination} ${m}분`).join(' · ')}</dd><dt>보행</dt><dd>${esc(p.walk)}</dd></dl></article>`).join('');shell(`<main class="print-sheet"><header class="print-sheet-head"><div><p>고등학교 통합사회 · 교육용 가상 자료</p><h1>이 버스는 누구를 지나치는가</h1><span>주민 이동 조건표 · 오전 07:00–10:00</span></div><div class="print-actions"><button class="portal-ghost" data-nav="">처음으로</button><button class="portal-primary" id="print-now">인쇄하기</button></div></header><section class="print-rule"><b>운영 조건</b><span>1호차는 ${STOP[BUS_STARTS[0]].name} 출발 · 2호차는 ${STOP[BUS_STARTS[1]].name} 출발 · 저상버스는 1대 · 환승 최대 1회</span></section><section class="print-grid">${cards}</section><footer>정류장이 있어도 출발 시각, 보행 조건, 노선, 차량 종류가 맞아야 실제로 목적지에 갈 수 있습니다.</footer></main>`,'print-mode');$('#print-now').addEventListener('click',()=>window.print());if(location.hash.includes('auto=1'))setTimeout(()=>window.print(),350);}
function renderTeacher(k){latestClass=k;const modal=qrOpen?qrModal(k):detailTeam?teamModal(k,detailTeam):'';shell(`${teacherHeader(k)}${dashboardBody(k)}${modal}`,'teacher-mode');bindTeacher(k);document.querySelectorAll('[data-action="print"]').forEach(el=>el.addEventListener('click',()=>window.open(`${location.origin}${location.pathname}#/print/residents?auto=1`,'_blank','noopener')));clearInterval(dashboardTimer);dashboardTimer=setInterval(()=>{const el=$('#teacher-timer');if(el)el.textContent=timeDisplay(remaining(latestClass));},1000);}
async function mountTeacher(code){dispose();clearInterval(dashboardTimer);currentCode=code;shell(`<div class="portal-loading">교사용 대시보드를 불러오는 중…</div>`,'teacher-mode');try{const {uid}=await connectBackend();const klass=await readClass(code);if(!klass){renderNotFound();return;}if(klass.teacherUid!==uid){shell(`<main class="join-page"><section class="join-form solo"><p class="portal-kicker">교사용 입장</p><h1>이 브라우저에서 만든 수업이 아닙니다.</h1><p>수업을 만든 교사 기기에서 대시보드를 열어 주세요.</p><button class="portal-ghost" data-nav="">처음으로</button></section></main>`,'portal-mode');return;}if(sessionStorage.getItem('bus-auto-qr')===code){qrOpen=true;sessionStorage.removeItem('bus-auto-qr');}dispose=watchClass(code,(value,error)=>{if(error){shell(`<div class="portal-loading error">${esc(firebaseMessage(error))}</div>`,'teacher-mode');return;}if(value)renderTeacher(value);});}catch(e){shell(`<div class="portal-loading error">${esc(firebaseMessage(e))}<button class="portal-primary" data-nav="">처음으로</button></div>`,'teacher-mode');}}
function bindTeacher(k){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',async()=>{const action=el.dataset.action;try{if(action==='qr'){qrOpen=true;detailTeam=null;renderTeacher(k);}if(action==='close-modal'){qrOpen=false;detailTeam=null;renderTeacher(k);}if(action==='copy-link'){await navigator.clipboard.writeText(`${location.origin}${location.pathname}#/join/${k.code}`);el.textContent='복사됨';}if(action==='preview')window.open(`${location.origin}${location.pathname}#/preview/${k.code}`,'_blank','noopener');if(action==='start')await updateControl(k.code,{status:'active',phaseStartedAt:'SERVER_TIME',pausedAt:0,message:stagePrompt(k.control.phase||0)});if(action==='pause'){if(k.control.status==='paused'){const elapsed=(k.control.pausedAt||Date.now())-(k.control.phaseStartedAt||Date.now());await updateControl(k.code,{status:'active',phaseStartedAt:Date.now()-elapsed,pausedAt:0});}else await updateControl(k.code,{status:'paused',pausedAt:Date.now()});}if(action==='extend')await updateControl(k.code,{phaseDuration:(k.control.phaseDuration||LESSON[k.control.phase][1])+1});if(action==='restart-timer')await updateControl(k.code,{phaseStartedAt:'SERVER_TIME',pausedAt:0,status:'active'});if(action==='next'){const phase=Math.min(6,(k.control.phase||0)+1);await updateControl(k.code,{phase,phaseDuration:LESSON[phase][1],phaseStartedAt:'SERVER_TIME',pausedAt:0,status:'active',message:stagePrompt(phase)});}if(action==='phase'){const phase=Number(el.dataset.phase);await updateControl(k.code,{phase,phaseDuration:LESSON[phase][1],phaseStartedAt:'SERVER_TIME',pausedAt:0,status:k.control.status==='lobby'?'lobby':'active',message:stagePrompt(phase)});}if(action==='broadcast'){const message=$('#broadcast').value.trim();await updateControl(k.code,{message});}if(action==='end')await updateControl(k.code,{status:'ended',pausedAt:Date.now()});if(action==='reopen')await updateControl(k.code,{status:'active',phaseStartedAt:'SERVER_TIME',pausedAt:0});if(action==='team'){detailTeam=el.dataset.team;qrOpen=false;renderTeacher(k);}if(action==='export')exportClass(k);}catch(e){alert(firebaseMessage(e));}}));}
function exportClass(k){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),classCode:k.code,control:k.control,teams:Object.values(k.teams||{}).map(t=>({name:t.name,joinedAt:t.joinedAt,progress:t.progress,studentState:t.studentState}))},null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`버스수업-${k.code}-결과.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function renderNotFound(){shell(`<main class="join-page"><section class="join-form solo"><p class="portal-kicker">수업 찾기</p><h1>이 수업을 찾을 수 없습니다.</h1><p>주소나 6자리 코드를 다시 확인해 주세요.</p><button class="portal-primary" data-nav="">처음으로</button></section></main>`,'portal-mode');}
async function showStandalone(){dispose();clearInterval(dashboardTimer);document.body.className='';app.innerHTML='';window.BUS_CLASSROOM=null;await import('./app.js');}
async function router(){dispose();dispose=()=>{};window.scrollTo(0,0);const parts=route();if(!parts.length)return renderLanding();if(parts[0]==='teacher'&&parts[1])return mountTeacher(parts[1]);if(parts[0]==='join'&&parts[1])return renderJoin(parts[1]);if(parts[0]==='preview'&&parts[1])return startPreview(parts[1]);if(parts[0]==='print'&&parts[1]==='residents')return renderPrint();if(parts[0]==='play')return showStandalone();renderNotFound();}
window.addEventListener('hashchange',()=>location.reload());router();
